/* ============ اقتراح الساعة المناسبة الآن + تذكيرات محلية ============
   ملحوظة: الستار صلاة رهبانية اختيارية غير مرتبطة بوقت ثابت للعموم،
   فهي مُستثناة عمدًا من الاقتراح التلقائي والتذكيرات، وتبقى متاحة للاختيار اليدوي دائمًا. */
const HOUR_AUTO_RANGES = [
  {key:"bakr",       start:4,    end:9},
  {key:"thalitha",   start:9,    end:11.5},
  {key:"sadisa",     start:11.5, end:14.5},
  {key:"tasi3a",     start:14.5, end:17},
  {key:"ghouroub",   start:17,   end:20},
  {key:"noum",       start:20,   end:24},
  {key:"nos_layl_1", start:0,    end:1.5},
  {key:"nos_layl_2", start:1.5,  end:3},
  {key:"nos_layl_3", start:3,    end:4}
];
const HOUR_REMINDER_TIMES = {
  bakr:6, thalitha:9, sadisa:12, tasi3a:15, ghouroub:17.5, noum:21,
  nos_layl_1:0, nos_layl_2:1.5, nos_layl_3:3
};
function getSuggestedHourKey(d){
  d = d || new Date();
  const dec = d.getHours() + d.getMinutes()/60;
  const found = HOUR_AUTO_RANGES.find(r => dec >= r.start && dec < r.end);
  return found ? found.key : "bakr";
}
function iconSvg(key, cls){
  return `<svg class="${cls}"><use href="#${HOUR_ICONS[key]||'icon-cross'}"></use></svg>`;
}

