/* attach shared opening + shared closing prayers to every active hour */
Object.keys(HOURS).forEach(key=>{
  const h = HOURS[key];
  if(!h.active) return;
  const items = commonOpeningItems().concat(h.specialOpening||[]);
  h.opening = {
    note:"هذه المقدمة الأساسية (الصلاة الربانية، صلاة الشكر، مزمور التوبة) مشتركة بين كل ساعات الأجبية من باكر حتى نصف الليل، وتُصلَّى قبل الدخول إلى مزامير كل ساعة. بعض الساعات تضيف مقدمة خاصة بها كما هو موضح.",
    items: items
  };
  h.recurring = {
    note:"هذه الصلوات الثابتة العشر مشتركة بين كل ساعات الأجبية، وتُصلَّى بعد القطع الخاصة بكل ساعة وقبل التحليل الختامي لها.",
    items: commonClosingItems()
  };
});

/* ============ STATE ============ */
function defaultMergedPartSel(){
  // كل قسم بيبني قيمته الافتراضية بنفسه أول ما يُعرض (شوف renderMergedPartsBody)،
  // عشان عدد وأسماء الأقسام بتختلف حسب عدد الساعات المدمجة (٢ أو ٣).
  return {};
}
let state = {hour:null, part:null, subIndex:0, openIndex:0, closeIndex:0, prayerTopic:null, prayerIdx:null, prayerAuthorFilter:null, prayerSearchQuery:'', prayerSearchResults:null, favOpenKey:null, pbBankOpen:false, mergeChecked:[], mergedPair:null, mergedContent:null, mergedPartSel:defaultMergedPartSel(), mergedClosingIdx:0};
const PB_FAV_TOPIC_KEY = '__fav__'; // sentinel pseudo-topic for the pooled favorites view

/* ============ RENDER ============ */
function openHoursDrawer(){
  document.getElementById('hoursDrawer').classList.add('open');
  document.getElementById('hoursBackdrop').classList.add('open');
}
function closeHoursDrawer(){
  document.getElementById('hoursDrawer').classList.remove('open');
  document.getElementById('hoursBackdrop').classList.remove('open');
}

function selectHour(key){
  state.hour=key; state.part=null; state.subIndex=0; state.openIndex=0; state.closeIndex=0;
  render();
}

/* الدمج يُسمح به فقط بين ساعات متتالية في الترتيب الكنسي (HOUR_ORDER)،
   بحد أقصى ٣ ساعات متتالية معًا — مش أي ساعتين عشوائيتين. */
function mergeCheckedIndexes(){
  return state.mergeChecked.map(k=>HOUR_ORDER.indexOf(k)).sort((a,b)=>a-b);
}
function isMergeSelectable(key){
  if(state.mergeChecked.includes(key)) return true;
  if(state.mergeChecked.length===0) return true;
  if(state.mergeChecked.length>=3) return false;
  const idx = HOUR_ORDER.indexOf(key);
  const idxs = mergeCheckedIndexes();
  return idx === idxs[0]-1 || idx === idxs[idxs.length-1]+1;
}
function canUncheckMerge(key){
  // لو الساعة دي في نص المجموعة المتتالية (مش أول واحدة ولا آخر واحدة)، منمنعش
  // شيلها مباشرة عشان منكسرش التتالي؛ لازم يشيل من الطرف الأول.
  if(!state.mergeChecked.includes(key)) return true;
  const idxs = mergeCheckedIndexes();
  const idx = HOUR_ORDER.indexOf(key);
  return idx === idxs[0] || idx === idxs[idxs.length-1];
}

function renderHours(){
  const grid = document.getElementById('hoursGrid');
  grid.innerHTML = '';
  const suggestedKey = getSuggestedHourKey();
  HOUR_ORDER.forEach(key=>{
    const h = HOURS[key];
    if(!h) return;
    const isSuggested = key===suggestedKey && state.hour!==key;
    const btn = document.createElement('div');
    btn.className = 'hour-btn' + (state.hour===key?' active':'') + (isSuggested?' suggested':'');
    btn.innerHTML = `${iconSvg(key,'hour-icon')}<div class="hour-btn-text"><div>${h.label}</div><div class="hour-btn-time">${HOUR_TIME[key]||''}</div></div>${isSuggested?'<span class="hour-btn-now-badge">الآن</span>':''}`;
    btn.onclick = ()=>{
      selectHour(key);
      closeHoursDrawer();
    };

    // Checkbox "دمج الصلوات": اختيار حتى ساعتين لدمجهما في صلاة واحدة (شوف
    // buildMergedHour). موضوع في عنصر مستقل مع stopPropagation عشان الضغط
    // عليه ميفتحش الساعة مباشرة زي ضغط بقية الزرار.
    const mergeWrap = document.createElement('span');
    mergeWrap.className = 'hour-merge-check';
    mergeWrap.title = 'اختر للدمج مع ساعة أخرى';
    mergeWrap.onclick = (e)=>{ e.stopPropagation(); };
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.checked = state.mergeChecked.includes(key);
    cb.disabled = cb.checked ? !canUncheckMerge(key) : !isMergeSelectable(key);
    cb.setAttribute('aria-label', 'دمج ' + h.label + ' مع الساعات المتتالية معها');
    cb.onclick = (e)=>{
      e.stopPropagation();
      if(cb.checked){
        if(isMergeSelectable(key) && !state.mergeChecked.includes(key)) state.mergeChecked.push(key);
      } else if(canUncheckMerge(key)){
        state.mergeChecked = state.mergeChecked.filter(k=>k!==key);
      }
      renderHours();
    };
    mergeWrap.appendChild(cb);
    btn.appendChild(mergeWrap);

    grid.appendChild(btn);
  });

  // شريط "دمج الصلوات": يظهر بمجرد اختيار ساعة واحدة على الأقل بالـCheckbox.
  const mergeBar = document.getElementById('hoursMergeBar');
  const mergeText = document.getElementById('hoursMergeText');
  if(mergeBar && mergeText){
    if(state.mergeChecked.length >= 2){
      mergeText.textContent = '';
      mergeBar.style.display = 'flex';
    } else if(state.mergeChecked.length === 1){
      mergeText.textContent = `اختر ساعة متتالية لدمجها مع ${HOURS[state.mergeChecked[0]].label}`;
      mergeBar.style.display = 'flex';
    } else {
      mergeBar.style.display = 'none';
    }
  }

  // Keep the always-visible trigger button in sync with the current selection.
  const triggerIcon = document.getElementById('hourTriggerIcon');
  const triggerValue = document.getElementById('hourTriggerValue');
  const triggerBtn = document.getElementById('hourTrigger');
  if(state.hour){
    triggerIcon.innerHTML = iconSvg(state.hour,'');
    triggerValue.textContent = HOURS[state.hour].label + ' — ' + HOURS[state.hour].sub;
    triggerBtn.classList.remove('pulse');
  } else if(state.mergedPair){
    const [mk1] = state.mergedPair;
    triggerIcon.innerHTML = iconSvg(mk1,'');
    triggerValue.textContent = '🔗 دمج الصلوات';
    triggerBtn.classList.remove('pulse');
  } else {
    triggerIcon.innerHTML = iconSvg('bakr','');
    triggerValue.textContent = 'اضغط هنا لاختيار ساعة الصلاة';
    triggerBtn.classList.add('pulse');
  }

  // بانر "الساعة المناسبة الآن" — يظهر فقط قبل اختيار المستخدم ساعة بنفسه.
  const suggestBox = document.getElementById('suggestNow');
  const suggestLabel = document.getElementById('suggestNowLabel');
  if(suggestBox){
    if(!state.hour && !state.mergedPair && HOURS[suggestedKey]){
      suggestLabel.textContent = HOURS[suggestedKey].label + ' — ' + HOURS[suggestedKey].sub;
      suggestBox.style.display = 'flex';
      suggestBox.dataset.key = suggestedKey;
    } else {
      suggestBox.style.display = 'none';
    }
  }
}

function fnList(list){
  return list.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener">${s.name}</a></li>`).join('');
}

function medBlock(item){
  /* v2.85: التأمل مطويّ افتراضيًا في كل الأوضاع (عادي/دمج) ويفتحه المستخدم بالضغط. */
  if(!item || !item.meditation || !item.meditation.length) return '';
  return `<details class="merged-meditation-toggle med-collapsible"${window.__medOpen()?' open':''}>
    <summary>✦ تأمل روحي</summary>
    <div class="meditation">
      ${item.meditation.map(p=>`<p>${p}</p>`).join('')}
      ${item.footnotes && item.footnotes.length ? `<div class="footnotes"><span class="fn-title">مراجع وحواشٍ:</span><ol>${fnList(item.footnotes)}</ol></div>` : ''}
    </div>
  </details>`;
}


/* ============ دمج ٢ أو ٣ ساعات متتالية في صلاة واحدة عند ضيق الوقت ============
   الترتيب الليتورجي المتّبع (بحسب تعليمات مينا، مبني بالكامل على نصوص
   موجودة فعلًا في التطبيق — لا نص جديد يُضاف):
   ١. مقدمة مدمجة (أبانا الذي، صلاة الشكر، المزمور الخمسون) — مرة واحدة فقط،
      وعنوانها الفرعي يسمّي الساعات المدمجة تحديدًا.
   ٢. مزمور واحد من كل ساعة (يُختار عشوائيًا)، في قسم واحد باختيارات.
   لكل ساعة بالترتيب:
      - إنجيل وقطعتها (+ «تفضل يا رب» لو هي النوم).
      - كيرياليسون وقدوس قدوس قدوس وأبانا الذي (فاصل بين كل ساعة والتالية لها فقط).
   ٧. الختام المشترك: السلام لكِ، مقدمة قانون الإيمان، قانون الإيمان،
      كيرياليسون، قدوس قدوس، أبانا الذي.
   ٨. تحليل كل ساعة، في قسم واحد باختيارات.
   ٩. ختام مدمج (ارحمنا يا الله ثم ارحمنا) — عنوانه الفرعي يسمّي الساعات المدمجة. */
function findCommonClosingById(id){
  return commonClosingItems().find(it=>it.id===id);
}
function pickRandomPsalm(hourKey){
  const items = HOURS[hourKey].parts.psalm.items;
  return items[Math.floor(Math.random()*items.length)];
}
