function renderMergedView(){
  const area = document.getElementById('mergedViewArea');
  if(!area) return;
  if(!state.mergedContent){ area.innerHTML=''; return; }
  const mc = state.mergedContent;
  const mergedHours = mc.hourKeys.map(k=>HOURS[k]);
  const mergedTag = mc.hourKeys.length===3 ? 'دمج ٣ صلوات متتالية' : 'دمج صلاتين متتاليتين';
  let html = `
    <div class="merged-view">
      <div class="merged-view-head">
        <button class="merged-back-btn" id="mergedBackBtn"><i class=chv>›</i> رجوع</button>
        <div class="merged-view-title">
          <span class="merged-view-tag">${mergedTag}</span>
          <h2>${mergedHours.map(h=>h.label).join(' + ')}</h2>
        </div>
      </div>
      <p class="merged-view-note">ترتيب مُقترح لدمج الساعات المتتالية عند ضيق الوقت؛ في دمج ثلاث صلوات تُعرض البنود بالتتابع كما تُصلّى. تقدر تدمج ساعات تانية في أي وقت من قائمة الساعات.</p>
  `;
  mc.sections.forEach((sec, i) => {
    const bodyHtml = sec.type==='parts'
      ? renderMergedPartsBody(sec)
      : sec.type==='chips'
      ? renderMergedChipsBody(sec)
      : sec.type==='reflectionFixed'
      ? renderMergedFixedReflectionBody(sec)
      : sec.items.map((it,j) => renderMergedCardHtml(it, (sec.tags&&sec.tags[j])||sec.title)).join('');
    html += `
      <details class="acc-card merged-section" id="mergedSection${i}"${sec.type==='parts' ? ` data-parts-prefix="${sec.prefix}"`:''}>
        <summary>
          <span class="acc-num">${i+1}</span>
          <span class="acc-title">${sec.title}${sec.sub ? `<span class="acc-sub">${sec.sub}</span>` : ''}</span>
          <span class="acc-caret">▾</span>
        </summary>
        <div class="acc-body">
          ${bodyHtml}
        </div>
      </details>
    `;
  });
  html += `</div>`;
  area.innerHTML = html;
  const backBtn = document.getElementById('mergedBackBtn');
  if(backBtn) backBtn.onclick = () => {
    state.mergedPair = null;
    state.mergedContent = null;
    state.mergedPartSel = defaultMergedPartSel();
    state.mergedClosingIdx = 0;
    render();
    window.scrollTo({top:0, behavior:'smooth'});
  };

  mc.sections.forEach((sec, i) => {
    const detailsEl = document.getElementById('mergedSection'+i);
    if(!detailsEl) return;
    if(sec.type==='parts'){
      detailsEl.querySelectorAll('.part-btn').forEach(btn=>{
        btn.onclick = ()=>{
          state.mergedPartSel[sec.prefix] = {part:btn.dataset.key, subIndex:0};
          render();
          const d = document.getElementById('mergedSection'+i);
          if(d){ d.open = true; scrollChipIntoView(d, '.part-btn.active'); }
        };
      });
      detailsEl.querySelectorAll('.sub-chip').forEach(chip=>{
        chip.onclick = ()=>{
          state.mergedPartSel[sec.prefix].subIndex = parseInt(chip.dataset.idx);
          render();
          const d = document.getElementById('mergedSection'+i);
          if(d){ d.open = true; scrollChipIntoView(d, '.sub-chip.active'); }
        };
      });
    } else if(sec.type==='chips'){
      detailsEl.querySelectorAll('.opening-chip').forEach(chip=>{
        chip.onclick = ()=>{
          state.mergedClosingIdx = parseInt(chip.dataset.idx);
          render();
          const d = document.getElementById('mergedSection'+i);
          if(d){ d.open = true; scrollChipIntoView(d, '.opening-chip.active'); }
        };
      });
    }
  });
}

