/* أي قائمة اختيارات أفقية قابلة للتمرير (opening-chip / sub-chip) بتتبني من
   جديد بالكامل (innerHTML) كل مرة تتغيّر فيها، فالمتصفح بيرجّع مكان
   التمرير (scrollLeft) لبدايته تلقائيًا قبل ما نلحق نمرّرها تاني للعنصر
   المختار — فيبان للمستخدم إن الليست "رجعت لأول عنصر" برغم إن اختياره
   اتسجّل صح. الحل: ننتظر فريمين (requestAnimationFrame مزدوج) بعد الرسم
   عشان نضمن إن المتصفح خلّص حساب المقاسات والتمرير الافتراضي الأول قبل
   ما نستخدم scrollIntoView لنرجّع العنصر المختار لمكانه في المنتصف. */
function scrollChipIntoView(area, selector){
  requestAnimationFrame(()=>{
    requestAnimationFrame(()=>{
      const el = area.querySelector(selector);
      if(el) el.scrollIntoView({behavior:'auto', inline:'center', block:'nearest'});
    });
  });
}

