function renderPartsSection(){
  const area = document.getElementById('partsSectionArea');
  const parts = currentParts();
  if(!parts){ area.innerHTML=''; return; }

  const partsRowHtml = Object.entries(parts).map(([key,p])=>
    `<div class="part-btn${state.part===key?' active':''}" data-key="${key}">${p.label}</div>`
  ).join('');

  let subScrollHtml = '';
  if(state.part && parts[state.part].items.length>1){
    subScrollHtml = `<div class="sub-scroll" style="display:flex;">
      ${parts[state.part].items.map((it,idx)=>
        `<div class="sub-chip${state.subIndex===idx?' active':''}" data-idx="${idx}">${it.subtitle}</div>`
      ).join('')}
    </div>`;
  }

  let contentHtml;
  if(!state.part){
    contentHtml = `<div class="placeholder">اختر جزء الصلاة أعلاه (المزمور / الإنجيل / القطعة / التحليل) لعرض النص والتأمل.</div>`;
  } else {
    const item = parts[state.part].items[state.subIndex];
    contentHtml = `
      <div class="content-card">
        <div class="content-head">
          ${iconSvg(state.hour,'hicon')}
          <span class="tag">${parts[state.part].label}</span>
          <h2>${item.title}${item.subtitle? ' — '+item.subtitle:''}</h2>
          <div class="ref">${item.ref}</div>
        </div>
        <div class="scripture">${item.text.map(v=>`<p>${v}</p>`).join('')}</div>
        ${medBlock(item)}
      </div>
    `;
  }

  area.innerHTML = `
    <details class="acc-card">
      <summary>
        <span class="acc-num">٥</span>
        <span class="acc-title">أجزاء الصلاة<span class="acc-sub">المزامير، الإنجيل، القطع، التحليل</span></span>
        <span class="acc-caret">▾</span>
      </summary>
      <div class="acc-body">
        <div class="parts-row">${partsRowHtml}</div>
        ${subScrollHtml}
        ${contentHtml}
      </div>
    </details>
  `;

  scrollChipIntoView(area, '.sub-chip.active');

  area.querySelectorAll('.part-btn').forEach(btn=>{
    btn.onclick = ()=>{ state.part = btn.dataset.key; state.subIndex = 0; render(); area.querySelector('details').open = true; };
  });
  area.querySelectorAll('.sub-chip').forEach(chip=>{
    chip.onclick = ()=>{ state.subIndex = parseInt(chip.dataset.idx); render(); area.querySelector('details').open = true; };
  });
}

function renderClosing(){
  const area = document.getElementById('closingArea');
  if(!state.hour){ area.innerHTML=''; return; }
  const h = HOURS[state.hour];
  if(!h.closing){ area.innerHTML=''; return; }
  area.innerHTML = `
    <details class="acc-card">
      <summary>
        <span class="acc-num">٦</span>
        <span class="acc-title">صلاة تأملية ختامية<span class="acc-sub">${h.closing.title}</span></span>
        <span class="acc-caret">▾</span>
      </summary>
      <div class="acc-body">
        <div class="closing" style="margin-top:0;">
          ${h.closing.lines.map(l=>`<p>${l}</p>`).join('')}
          <div class="amen">${h.closing.amen}</div>
        </div>
      </div>
    </details>
  `;
}

/* ============ SECTION: personal prayer bank (static, home page only) ============ */
/* ---- favorite (star) prayers in the personal prayer bank ----
   Purely additive — stored client-side in localStorage, no server, no
   effect on the underlying PRAYER_TOPICS data or any other feature. */
const PB_FAV_KEY = 'khalwa_pb_favorites_v1';
function loadFavoritePrayers(){
  try{
    const raw = localStorage.getItem(PB_FAV_KEY);
    return raw ? new Set(JSON.parse(raw)) : new Set();
  }catch(e){ return new Set(); }
}
function saveFavoritePrayers(set){
  try{ localStorage.setItem(PB_FAV_KEY, JSON.stringify([...set])); }catch(e){}
}
function isFavoritePrayer(topicKey, idx){
  return loadFavoritePrayers().has(topicKey+'::'+idx);
}
function toggleFavoritePrayer(topicKey, idx){
  const set = loadFavoritePrayers();
  const key = topicKey+'::'+idx;
  if(set.has(key)) set.delete(key); else set.add(key);
  saveFavoritePrayers(set);
}

function renderPersonalPrayer(){
  const area = document.getElementById('personalPrayerArea');
  if(state.hour || state.mergedPair){ area.innerHTML=''; return; }

  const favCount = loadFavoritePrayers().size;
  const favChipHtml = `
    <div class="pb-topic-chip pb-fav-chip${state.prayerTopic===PB_FAV_TOPIC_KEY?' active':''}" data-key="${PB_FAV_TOPIC_KEY}">
      <span class="pb-fav-chip-star">★</span>
      <span>المفضلة</span>
      ${favCount ? `<span class="pb-topic-count">${favCount}</span>` : ''}
    </div>
  `;
  const topicsHtml = favChipHtml + PRAYER_TOPICS.map(t => `
    <div class="pb-topic-chip${state.prayerTopic===t.key?' active':''}" data-key="${t.key}">
      <svg class="pb-topic-icon"><use href="#${t.icon}"></use></svg>
      <span>${t.label}</span>
      ${t.prayers.length ? `<span class="pb-topic-count">${t.prayers.length}</span>` : ''}
    </div>
  `).join('');

  let bodyHtml;

  if(state.prayerTopic === PB_FAV_TOPIC_KEY){
    // ---- pooled "المفضلة" view across every topic ----
    const favSet = loadFavoritePrayers();
    const favItems = [];
    PRAYER_TOPICS.forEach(t=>{
      t.prayers.forEach((p, idx)=>{
        if(favSet.has(t.key+'::'+idx)) favItems.push({ p, idx, topic: t });
      });
    });
    if(favItems.length === 0){
      bodyHtml = `<div class="placeholder">لسه مفيش صلوات في المفضلة — اضغط ⭐ جنب أي صلاة لإضافتها هنا.</div>`;
    } else {
      bodyHtml = `<div class="pb-prayer-list">` + favItems.map(({p, idx, topic: t}) => {
        const favKey = t.key+'::'+idx;
        const open = state.favOpenKey === favKey;
        return `
          <div class="pb-prayer-item${open?' open':''}" data-topic="${t.key}" data-idx="${idx}" data-favkey="${favKey}">
            <button class="pb-prayer-toggle" data-topic="${t.key}" data-idx="${idx}" data-favkey="${favKey}">
              <span class="pb-fav-star active" data-topic="${t.key}" data-idx="${idx}" title="إزالة من المفضلة" role="button" tabindex="0">★</span>
              <span class="pb-prayer-toggle-text">
                <span class="pb-prayer-title">${p.title}</span>
                <span class="pb-prayer-source"><strong>${t.label}</strong>${p.author ? ` — ${p.author}` : ''} — ${p.source}</span>
              </span>
              <span class="pb-prayer-caret">▾</span>
            </button>
            ${open ? `
              <div class="content-card pb-prayer-body">
                <div class="scripture">${p.text.map(v=>`<p>${v}</p>`).join('')}</div>
                <div class="footnotes">
                  <span class="fn-title">مراجع وحواشٍ:</span>
                  <ol>${fnList(p.footnotes)}</ol>
                </div>
              </div>
            ` : ''}
          </div>
        `;
      }).join('') + `</div>`;
    }

    area.innerHTML = `
      <details class="acc-card" id="ppDetails"${state.pbBankOpen ? ' open' : ''}>
        <summary>
          <span class="acc-num">✠</span>
          <span class="acc-title">بنك الصلوات الشخصية<span class="acc-sub">اختر موضوعًا يشغل قلبك — صلوات مختارة من كتابات البابا شنودة الثالث وتراث الكنيسة، متاحة دائمًا بلا إنترنت</span></span>
          <span class="acc-caret">▾</span>
        </summary>
        <div class="acc-body">
          <div class="pb-topics">${topicsHtml}</div>
          ${bodyHtml}
        </div>
      </details>
    `;

    area.querySelectorAll('.pb-topic-chip').forEach(chip=>{
      chip.onclick = ()=>{
        state.prayerTopic = (state.prayerTopic === chip.dataset.key) ? null : chip.dataset.key;
        state.prayerIdx = null;
        state.favOpenKey = null;
        state.prayerAuthorFilter = null;
        state.prayerSearchQuery = '';
        state.prayerSearchResults = null;
        render();
        const d = document.getElementById('ppDetails');
        if(d) d.open = true;
      };
    });

    area.querySelectorAll('.pb-prayer-toggle').forEach(btn=>{
      btn.onclick = ()=>{
        const favKey = btn.dataset.favkey;
        state.favOpenKey = (state.favOpenKey === favKey) ? null : favKey;
        render();
      };
    });

    area.querySelectorAll('.pb-fav-star').forEach(star=>{
      const toggle = (e)=>{
        e.preventDefault();
        e.stopPropagation();
        toggleFavoritePrayer(star.dataset.topic, parseInt(star.dataset.idx, 10));
        render();
      };
      star.addEventListener('click', toggle);
      star.addEventListener('keydown', (e)=>{
        if(e.key==='Enter' || e.key===' '){ toggle(e); }
      });
    });

    wirePbDetailsToggle();
    return; // favorites view fully wired — skip the per-topic branch below
  }

  const topic = PRAYER_TOPICS.find(t => t.key === state.prayerTopic);
  if(!topic){
    bodyHtml = `<div class="placeholder">اختر موضوعًا أعلاه لعرض الصلوات الخاصة به.</div>`;
  } else if(topic.prayers.length === 0){
    bodyHtml = `<div class="placeholder">موضوع «${topic.label}» قيد الإعداد — يُضاف قريبًا بصلوات موثقة من مصادرها.</div>`;
  } else {
    const hasAuthors = topic.prayers.some(p => p.author);
    let searchHtml = '';
    let visiblePrayers = topic.prayers;

    if(hasAuthors){
      const authors = [...new Set(topic.prayers.map(p => p.author).filter(Boolean))];
      if(state.prayerAuthorFilter && authors.includes(state.prayerAuthorFilter)){
        visiblePrayers = topic.prayers.filter(p => p.author === state.prayerAuthorFilter);
      }
      const authorOptions = authors.map(a => `<option value="${a}">`).join('');
      let nameResultsHtml = '';
      if(state.prayerSearchResults){
        nameResultsHtml = state.prayerSearchResults.length
          ? `<div class="pb-search-results">${state.prayerSearchResults.map(r => `<button type="button" class="pb-search-result" data-idx="${r.idx}">${r.title}</button>`).join('')}</div>`
          : `<div class="pb-search-results"><div class="pb-search-noresults">لا توجد صلاة بهذا الاسم</div></div>`;
      }
      searchHtml = `
        <div class="pb-search-row">
          <div class="pb-search-field">
            <label for="pbSearchName">Search — بحث بأقرب اسم للصلاة</label>
            <div class="pb-search-inline">
              <input type="text" id="pbSearchName" placeholder="اكتب اسم الصلاة..." autocomplete="off" value="${state.prayerSearchQuery || ''}">
              <button type="button" id="pbSearchBtn">بحث</button>
            </div>
            ${nameResultsHtml}
          </div>
          <div class="pb-search-field">
            <label for="pbSearchAuthor">By Name — بحث بأقرب اسم لقائل الصلاة</label>
            <input type="text" id="pbSearchAuthor" list="pbAuthorList" placeholder="اكتب أو اختر اسم القديس..." autocomplete="off" value="${state.prayerAuthorFilter || ''}">
            <datalist id="pbAuthorList">${authorOptions}</datalist>
          </div>
          ${state.prayerAuthorFilter ? `<button class="pb-search-clear" id="pbClearAuthor" type="button">✕ إظهار الكل (${topic.prayers.length})</button>` : ''}
        </div>
      `;
    }

    bodyHtml = searchHtml + `<div class="pb-prayer-list">` + visiblePrayers.map((p) => {
      const idx = topic.prayers.indexOf(p);
      const open = state.prayerIdx === idx;
      const isFav = isFavoritePrayer(topic.key, idx);
      return `
        <div class="pb-prayer-item${open?' open':''}" data-idx="${idx}">
          <button class="pb-prayer-toggle" data-idx="${idx}">
            <span class="pb-fav-star${isFav?' active':''}" data-topic="${topic.key}" data-idx="${idx}" title="${isFav?'إزالة من المفضلة':'أضف إلى المفضلة'}" role="button" tabindex="0">★</span>
            <span class="pb-prayer-toggle-text">
              <span class="pb-prayer-title">${p.title}</span>
              <span class="pb-prayer-source">${p.author ? `<strong>${p.author}</strong> — ` : ''}${p.source}</span>
            </span>
            <span class="pb-prayer-caret">▾</span>
          </button>
          ${open ? `
            <div class="content-card pb-prayer-body">
              <div class="scripture">${p.text.map(v=>`<p>${v}</p>`).join('')}</div>
              <div class="footnotes">
                <span class="fn-title">مراجع وحواشٍ:</span>
                <ol>${fnList(p.footnotes)}</ol>
              </div>
            </div>
          ` : ''}
        </div>
      `;
    }).join('') + `</div>`;
    if(visiblePrayers.length === 0){
      bodyHtml += `<div class="placeholder">لا توجد صلوات لهذا القديس ضمن هذا الموضوع.</div>`;
    }
  }

  area.innerHTML = `
    <details class="acc-card" id="ppDetails"${state.pbBankOpen ? ' open' : ''}>
      <summary>
        <span class="acc-num">✠</span>
        <span class="acc-title">بنك الصلوات الشخصية<span class="acc-sub">اختر موضوعًا يشغل قلبك — صلوات مختارة من كتابات البابا شنودة الثالث وتراث الكنيسة، متاحة دائمًا بلا إنترنت</span></span>
        <span class="acc-caret">▾</span>
      </summary>
      <div class="acc-body">
        <div class="pb-topics">${topicsHtml}</div>
        ${bodyHtml}
      </div>
    </details>
  `;

  area.querySelectorAll('.pb-topic-chip').forEach(chip=>{
    chip.onclick = ()=>{
      state.prayerTopic = (state.prayerTopic === chip.dataset.key) ? null : chip.dataset.key;
      state.prayerIdx = null;
      state.favOpenKey = null;
      state.prayerAuthorFilter = null;
      state.prayerSearchQuery = '';
      state.prayerSearchResults = null;
      render();
      const d = document.getElementById('ppDetails');
      if(d) d.open = true;
    };
  });

  area.querySelectorAll('.pb-prayer-toggle').forEach(btn=>{
    btn.onclick = ()=>{
      const idx = parseInt(btn.dataset.idx, 10);
      state.prayerIdx = (state.prayerIdx === idx) ? null : idx;
      render();
    };
  });

  area.querySelectorAll('.pb-fav-star').forEach(star=>{
    const toggle = (e)=>{
      e.preventDefault();
      e.stopPropagation();
      toggleFavoritePrayer(star.dataset.topic, parseInt(star.dataset.idx, 10));
      render();
    };
    star.addEventListener('click', toggle);
    star.addEventListener('keydown', (e)=>{
      if(e.key==='Enter' || e.key===' '){ toggle(e); }
    });
  });

  const nameInput = document.getElementById('pbSearchName');
  const searchBtn = document.getElementById('pbSearchBtn');
  if(nameInput && searchBtn){
    const runSearch = ()=>{
      const q = nameInput.value.trim();
      const t = PRAYER_TOPICS.find(t => t.key === state.prayerTopic);
      if(!t) return;
      state.prayerSearchQuery = q;
      if(!q){
        state.prayerSearchResults = null;
        render();
        return;
      }
      const matches = t.prayers
        .map((p, idx) => ({ p, idx }))
        .filter(({p}) => p.title.includes(q));
      state.prayerSearchResults = matches.map(({p, idx}) => ({ idx, title: p.title }));
      render();
    };
    searchBtn.onclick = runSearch;
    nameInput.addEventListener('keydown', e=>{ if(e.key==='Enter'){ e.preventDefault(); runSearch(); }});
  }

  area.querySelectorAll('.pb-search-result').forEach(btn=>{
    btn.onclick = ()=>{
      const idx = parseInt(btn.dataset.idx, 10);
      state.prayerAuthorFilter = null; // clear author filter so the selected prayer is guaranteed visible
      state.prayerIdx = idx;
      state.prayerSearchResults = null; // collapse the results list once a choice is made
      render();
      requestAnimationFrame(()=>{
        const el = area.querySelector(`.pb-prayer-item[data-idx="${idx}"]`);
        if(el) el.scrollIntoView({behavior:'smooth', block:'center'});
      });
    };
  });

  const authorInput = document.getElementById('pbSearchAuthor');
  if(authorInput){
    const jumpToAuthor = ()=>{
      const q = authorInput.value.trim();
      if(!q) return;
      const t = PRAYER_TOPICS.find(t => t.key === state.prayerTopic);
      if(!t) return;
      const authors = [...new Set(t.prayers.map(p=>p.author).filter(Boolean))];
      let match = authors.find(a => a === q);
      if(!match) match = authors.find(a => a.includes(q));
      if(match){
        state.prayerAuthorFilter = match;
        state.prayerIdx = null;
        render();
      }
    };
    authorInput.addEventListener('change', jumpToAuthor);
    authorInput.addEventListener('keydown', e=>{ if(e.key==='Enter'){ e.preventDefault(); jumpToAuthor(); }});
  }

  const clearAuthorBtn = document.getElementById('pbClearAuthor');
  if(clearAuthorBtn){
    clearAuthorBtn.onclick = ()=>{
      state.prayerAuthorFilter = null;
      state.prayerIdx = null;
      render();
    };
  }

  wirePbDetailsToggle();
}

// يحفظ حالة فتح/قفل «بنك الصلوات الشخصية» في state، عشان تفضل زي ما هي
// (مفتوحة لو المستخدم فتحها بنفسه) عبر كل إعادة رسم يسببها اختيار موضوع أو صلاة،
// لكن تُقفَل تلقائيًا عند فتح التطبيق أول مرة أو الضغط على 🏠 (شوف goHome()).
function wirePbDetailsToggle(){
  const d = document.getElementById('ppDetails');
  if(d) d.addEventListener('toggle', ()=>{ state.pbBankOpen = d.open; });
}

// «رسالة من الله»: تُختار رسالة واحدة عشوائيًا من رسائل الساعة المقترحة الآن (٣-٤ رسائل
// لكل ساعة، كل واحدة بوحي مزمور فعلي من مزامير تلك الساعة). تبقى الرسالة المختارة ثابتة
// طالما الساعة المقترحة لم تتغيّر بعد؛ وبمجرد أن يتغيّر الوقت لساعة أخرى، تُختار رسالة
// جديدة عشوائيًا من مجموعة الساعة الجديدة (انظر godMessageState).
function renderGodMessage(){
  const area = document.getElementById('godMessageArea');
  if(!area) return;
  if(state.hour || state.mergedPair){ area.innerHTML=''; return; }

  const key = getSuggestedHourKey();
  const pool = HOUR_MESSAGES[key] || HOUR_MESSAGES.bakr;
  if(godMessageState.hourKey !== key || godMessageState.index==null || godMessageState.index >= pool.length){
    godMessageState.hourKey = key;
    godMessageState.index = Math.floor(Math.random()*pool.length);
  }
  const msg = pool[godMessageState.index] || pool[0];

  area.innerHTML = `
    <div class="god-message-card">
      <div class="god-message-title">رسالة من الله لك الآن</div>
      <p class="god-message-text">"${msg.text}"</p>
      <div class="god-message-ref">بوحي من ${msg.ref} — ${HOURS[key] ? HOURS[key].label : ''}</div>
      <div class="god-message-note">تأمّل حرّ مبني على معنى المزمور المذكور، وليس اقتباسًا حرفيًا أو وحيًا جديدًا.</div>
    </div>
  `;
}

function render(){
  renderHours();
  renderMergedView();
  renderIntro();
  renderOpeningReflection();
  renderOpening();
  renderRecurring();
  renderPartsSection();
  renderClosing();
  renderPersonalPrayer();
  renderGodMessage();
}
render();

// إعادة رسم شبكة الساعات كل دقيقة بس، عشان شارة "الآن" وبانر الاقتراح ورسالة الله
// يتحدّثوا مع مرور الوقت من غير ما نلمس أي جزء تاني من الصفحة (لا سكرول ولا فتح/قفل).
setInterval(()=>{ renderHours(); renderGodMessage(); }, 60000);

const suggestNowBtnEl = document.getElementById('suggestNowBtn');
if (suggestNowBtnEl) {
  suggestNowBtnEl.onclick = () => {
    const key = document.getElementById('suggestNow').dataset.key;
    if (key) selectHour(key);
  };
}


