function renderMeditation(d) {
  currentMeditation = d;
  d.variant = currentVariant;
  contentEl.innerHTML = buildCardInnerHTML(d);
  buildTabs();
  updateFavBtn();
}

// The model returns JSON, but it can arrive wrapped in prose/markdown
// or contain raw newlines inside string values (common with the
// multi-line prayer), both of which break a naive JSON.parse.
function parseModelJson(text) {
  let clean = text.replace(/```json|```/g, "").trim();

  // Keep only the outermost JSON object.
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) {
    throw new Error('لم يصل JSON صالح من النموذج');
  }
  clean = clean.slice(start, end + 1);

  try {
    return JSON.parse(clean);
  } catch (e) {
    // Repair literal newlines/tabs that appear inside quoted strings.
    let repaired = '';
    let inString = false, escaped = false;
    for (const ch of clean) {
      if (escaped) { repaired += ch; escaped = false; continue; }
      if (ch === '\\') { repaired += ch; escaped = true; continue; }
      if (ch === '"') { inString = !inString; repaired += ch; continue; }
      if (inString && (ch === '\n' || ch === '\r')) { repaired += '\\n'; continue; }
      if (inString && ch === '\t') { repaired += '\\t'; continue; }
      repaired += ch;
    }
    return JSON.parse(repaired);
  }
}

// The API here supports max_tokens of 1000, and a full meditation in
// Arabic (which is very token-heavy) does not fit in a single reply —
// asking for more returns an internal server error. So each meditation
// is fetched in two smaller calls that are merged together.
// The API model string that actually resolves can vary; try a few and
// remember the first one that works so later calls go straight to it.
const CANDIDATE_MODELS = [
  "claude-sonnet-4-6",
  "claude-sonnet-5",
  "claude-haiku-4-5-20251001"
];
let workingModel = null;

async function requestModel(model, prompt) {
  const response = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: model,
      max_tokens: 1000,
      messages: [{ role: "user", content: prompt }]
    })
  });

  let responseData;
  try {
    responseData = await response.json();
  } catch (e) {
    throw new Error('رد غير مقروء من الخادم (' + response.status + ')');
  }

  if (!response.ok || responseData.error) {
    throw new Error(
      (responseData.error && responseData.error.message)
        ? responseData.error.message
        : ('الخادم رجّع خطأ ' + response.status)
    );
  }
  if (!Array.isArray(responseData.content)) {
    throw new Error('رد غير متوقع من الخادم');
  }

  return responseData.content
    .filter(b => b.type === "text")
    .map(b => b.text)
    .join("\n");
}

async function callClaudeJson(prompt) {
  let lastError = null;

  // If we already know a model that works, try it (with one retry for
  // a transient hiccup) before falling back to probing the others.
  const order = workingModel
    ? [workingModel, ...CANDIDATE_MODELS.filter(m => m !== workingModel)]
    : CANDIDATE_MODELS;

  for (const model of order) {
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const text = await requestModel(model, prompt);
        const parsed = parseModelJson(text);
        workingModel = model;
        return parsed;
      } catch (err) {
        lastError = err;
      }
    }
  }
  throw lastError;
}

async function callClaudeForVariant(dateStr, weekdayAr, topic, variant) {
  const spec = VARIANTS.find(v => v.n === variant);
  const topicLine = topic
    ? `الموضوع الروحي محدد مسبقًا وهو: "${topic}". لا تغيّره.`
    : `اختر موضوعًا روحيًا واحدًا مختلفًا عن هذه المواضيع: ${Array.from(usedTopics).join('، ') || 'لا يوجد'}.`;

  const context = `أنت تساعد خادم مدارس أحد قبطي أرثوذكسي في إعداد تأمل روحي يومي لطلاب المرحلة الثانوية.
التاريخ: ${dateStr} (${weekdayAr}).
${topicLine}
هذا التأمل رقم ${variant} من خمسة تأملات في نفس الموضوع، فاجعله مختلفًا تمامًا عن غيره.
${spec.spec}`;

  // Part 1: verse + patristic quote + reflection.
  const promptA = `${context}

اختر آية واحدة من الكتاب المقدس مناسبة للموضوع مع اسم السفر والإصحاح والعدد بالعربية.
أضف فقرة قصيرة بأسلوبك (إعادة صياغة لا اقتباس حرفي) مستوحاة من فكر أحد آباء الكنيسة القبطية الأرثوذكسية، يفضل القمص تادرس يعقوب ملطي أو البابا شنوده الثالث.
اكتب تأملًا من 3 إلى 4 جمل يربط الآية بحياة المراهق.
اكتب عنوانًا شعريًا قصيرًا مستوحى من معنى الآية (title2).
اختر مرجعًا واحدًا من: st-takla.org أو anba-abraam.com أو popeshenouda.org.eg أو coptic-treasures.com أو christianlib.com أو stmark-kw.net أو library.awtar-alsama.com.

أعد JSON فقط بدون أي نص أو Markdown حوله:
{"topic":"...","title2":"...","ref":"...","verse":"...","father":"...","quote":"...","reflect":"...","source":"المرجع: ...، اسم_الموقع"}`;

  const partA = await callClaudeJson(promptA);

  // Part 2: the prayer (long) plus any variant-specific extra block.
  const promptB = `${context}

الموضوع: "${topic || partA.topic}"
الآية: "${partA.verse}" (${partA.ref})

اكتب صلاة موجهة مباشرة للرب يسوع، لا تقل عن 8 أسطر (كل سطر جملة منفصلة)، عميقة وتحرك القلب، منتهية بكلمة "آمين."
مهم جدًا: داخل قيمة "prayer" استخدم \\n للفصل بين الأسطر ولا تضع أسطرًا حقيقية جديدة.

أعد JSON فقط بدون أي نص أو Markdown حوله:
{"prayer":"سطر1\\nسطر2\\nسطر3\\nسطر4\\nسطر5\\nسطر6\\nسطر7\\nآمين.\nيا رب، لا تترك هذا التأمل في ... حبيس الكلمات، بل حوّله إلى حياة.\nامنحني في اليوم هذا نعمة أعيش بها ما صليتُ به الآن.\nيا رب، إن نسيتُ كل شيء آخر اليوم، فلا أنسَ أنك تكلمتَ معي عن ....\nآمين.","extraLabel":"","extraText":"","extraRef":""}`;

  const partB = await callClaudeJson(promptB);

  const merged = Object.assign({}, partA, partB);
  if (!merged.verse || !merged.prayer) {
    throw new Error('التأمل رجع ناقص');
  }
  return merged;
}

async function selectVariant(n) {
  if (!currentKey || !pool[currentKey]) return;
  closeFavPanel();
  currentVariant = n;
  buildTabs();

  const entry = pool[currentKey];
  if (entry.variants[n]) {
    renderMeditation(entry.variants[n]);
    statusLine.textContent = '';
    return;
  }

  // Fallback path (kept for safety): all 7 khalwa topics ship with all 5
  // variants pre-written, so this should not normally run.
  const { dateStr, weekdayAr } = todaysArabicDateLabel();
  const d = entry.variants[1] || { date: dateStr, weekday: weekdayAr };
  statusLine.innerHTML = `جارٍ تجهيز تأمل ${n}<span class="spinner"></span>`;
  variantTabsEl.querySelectorAll('button').forEach(b => b.disabled = true);

  try {
    const generated = await callClaudeForVariant(dateStr, weekdayAr, entry.topic, n);
    generated.date = dateStr;
    generated.weekday = weekdayAr;
    generated.day = d.day;
    generated.variant = n;
    generated.topic = entry.topic || generated.topic;
    entry.variants[n] = generated;
    renderMeditation(generated);
    statusLine.textContent = '';
  } catch (err) {
    console.error(err);
    statusLine.textContent = 'تعذّر تجهيز هذا التأمل الآن. حاول مرة أخرى لاحقًا.';
  } finally {
    variantTabsEl.querySelectorAll('button').forEach(b => b.disabled = false);
  }
}

function todaysArabicDateLabel() {
  return {
    dateStr: `${todayDay} ${arMonths[todayMonth - 1]} ${thisYear}`,
    weekdayAr: arWeekdays[today.getDay()]
  };
}

function loadTodaysKhalwa() {
  const key = todaysPoolKey();
  currentKey = key;
  currentVariant = (pool[key] && pool[key].year) ? (((thisYear - 2026) % 3) + 3) % 3 + 1 : 1;

  if (!key) {
    statusLine.textContent = 'تعذّر تجهيز خلوة اليوم.';
    return;
  }

  // The pool's stored date/weekday belong to whichever day the topic was
  // originally authored for, not to today. Overwrite them on every variant
  // of today's chosen topic so the header, the card, and the saved
  // screenshot all show the real current date regardless of which variant
  // tab is open.
  const { dateStr, weekdayAr } = todaysArabicDateLabel();
  Object.values(pool[key].variants).forEach(v => {
    v.date = dateStr;
    v.weekday = weekdayAr;
    try { const _cl = window.__copCal && window.__copCal.label(today); if (_cl && _cl.text && pool[key].year) v.weekday = weekdayAr + ' · ' + _cl.text; } catch (e) {}
  });

  const v1 = pool[key].variants[currentVariant] || pool[key].variants[1];
  v1.variant = currentVariant;
  renderMeditation(v1);
  khalwaHeaderEl.textContent = `${v1.date} — ${v1.weekday} · موضوع اليوم: ${pool[key].topic}`;
  statusLine.textContent = '';
}

/* ============ المفضلة للتأملات اليومية ============
   كل تأمل يتحفظ بتاريخ اليوم اللي ظهر فيه + رقم التأمل (١–٥)، مع نسخة كاملة
   من نصه، عشان يفضل ثابت حتى لو التأمل اتكرر في يوم تاني. localStorage فقط. */
const MED_FAV_KEY = 'khalwa_med_favs_v1';
function loadMedFavs(){
  try{ const r = localStorage.getItem(MED_FAV_KEY); return r ? JSON.parse(r) : {}; }catch(e){ return {}; }
}
function saveMedFavs(o){ try{ localStorage.setItem(MED_FAV_KEY, JSON.stringify(o)); }catch(e){} }
function medFavId(variant){ return `${thisYear}-${todayMonth}-${todayDay}#${variant}`; }
function toggleMedFav(){
  if(!currentMeditation) return;
  const favs = loadMedFavs();
  const id = medFavId(currentVariant);
  if(favs[id]) delete favs[id];
  else favs[id] = { dateKey:`${thisYear}-${todayMonth}-${todayDay}`, variant:currentVariant, savedAt:Date.now(), med:Object.assign({}, currentMeditation, {variant:currentVariant}) };
  saveMedFavs(favs);
  updateFavBtn();
  if(document.getElementById('favPanel').classList.contains('open')) renderFavPanel();
}
function updateFavBtn(){
  const on = !!loadMedFavs()[medFavId(currentVariant)];
  const btn = document.getElementById('favToggleBtn');
  if(!btn) return;
  btn.classList.toggle('fav-on', on);
  document.getElementById('favToggleStar').textContent = on ? '★' : '☆';
  document.getElementById('favToggleLabel').textContent = on ? 'في المفضلة' : 'أضف للمفضلة';
  const n = Object.keys(loadMedFavs()).length;
  document.getElementById('favOpenLabel').textContent = n ? `المفضلة (${n})` : 'المفضلة';
}
let favOpenId = null;
function renderFavPanel(){
  const favs = loadMedFavs();
  const ids = Object.keys(favs).sort((a,b)=> favs[b].savedAt - favs[a].savedAt);
  const list = document.getElementById('favList');
  const card = document.getElementById('favCardContent');
  if(!ids.length){
    list.innerHTML = '<div class="fav-empty">لسه مفيش تأملات في المفضلة — اضغط ☆ أضف للمفضلة على أي تأمل.</div>';
    card.innerHTML = ''; card.closest('.card-outer').style.display='none'; favOpenId=null; return;
  }
  if(!favOpenId || !favs[favOpenId]) favOpenId = ids[0];
  list.innerHTML = ids.map(id=>{
    const f = favs[id], m = f.med;
    return `<div class="fav-item${id===favOpenId?' active':''}" data-id="${id}">
      <span class="fav-item-text"><span class="fav-item-date">${m.date} — تأمل ${f.variant}</span><span class="fav-item-sub">${m.topic} · ${m.title2}</span></span>
      <span class="fav-item-star" data-unfav="${id}" role="button" aria-label="إزالة من المفضلة">★</span></div>`;
  }).join('');
  card.closest('.card-outer').style.display='';
  card.innerHTML = buildCardInnerHTML(favs[favOpenId].med);
  list.querySelectorAll('.fav-item').forEach(el=>{
    el.onclick = ()=>{ favOpenId = el.dataset.id; renderFavPanel(); };
  });
  list.querySelectorAll('[data-unfav]').forEach(el=>{
    el.onclick = (e)=>{
      e.stopPropagation();
      const f = loadMedFavs(); delete f[el.dataset.unfav]; saveMedFavs(f);
      updateFavBtn(); renderFavPanel();
    };
  });
}
function openFavPanel(){
  document.getElementById('favPanel').classList.add('open');
  document.getElementById('todayCardOuter').style.display='none';
  document.getElementById('favOpenLabel').textContent='رجوع لتأمل اليوم';
  renderFavPanel();
}
function closeFavPanel(){
  const p = document.getElementById('favPanel');
  if(!p || !p.classList.contains('open')) return;
  p.classList.remove('open');
  document.getElementById('todayCardOuter').style.display='';
  updateFavBtn();
}
document.getElementById('favToggleBtn').addEventListener('click', toggleMedFav);
document.getElementById('favOpenBtn').addEventListener('click', ()=>{
  document.getElementById('favPanel').classList.contains('open') ? closeFavPanel() : openFavPanel();
});

window.__favApi={
  prayers:function(){ var set=loadFavoritePrayers(), out=[]; PRAYER_TOPICS.forEach(function(t){ t.prayers.forEach(function(p,idx){ if(set.has(t.key+'::'+idx)) out.push({key:t.key+'::'+idx,topic:t.label,title:p.title,author:p.author||'',source:p.source||'',text:p.text||[]}); }); }); return out; },
  unPrayer:function(k){ var s=loadFavoritePrayers(); s.delete(k); saveFavoritePrayers(s); }
};
buildTabs();
loadTodaysKhalwa();

// Chrome refuses to export a canvas drawn from HTML content, and the
// raster libraries that can export break Arabic letter-joining. So we
// show the real card scaled to fit exactly one screen instead: the text
// is rendered natively (perfect shaping) and one screenshot captures
// the whole card.
// Chrome refuses to export a canvas drawn from HTML content, and the
// raster libraries that can export break Arabic letter-joining. So we
// show the real card scaled to fit exactly one screen instead: the text
// is rendered natively (perfect shaping) and one screenshot captures
// the whole card. The content area is scaled — up for short meditations,
// down for long ones — to a target height computed from the actual
// viewport, so every card (any day, any variant) fills the screen the
// same way, not just matches whichever meditation happened to be
// screenshotted first.

saveBtn.addEventListener('click', async () => {
  if (!currentMeditation) return;

  if (document.fonts && document.fonts.ready) {
    await document.fonts.ready;
  }

  document.getElementById('exportContent').innerHTML = buildCardInnerHTML(currentMeditation);

  const overlay = document.getElementById('shotOverlay');
  const stage = document.getElementById('shotStage');
  const card = document.querySelector('#exportHost .export-card');

  stage.innerHTML = '';
  const cardForShot = card.cloneNode(true);
  cardForShot.style.flex = '0 0 auto';
  cardForShot.style.width = '1080px';
  stage.appendChild(cardForShot);
  overlay.classList.add('open');

  requestAnimationFrame(() => {
    /* v73: «صلاة القلب» في الصورة فقرة متصلة بدل سطر قصير لكل جملة (النص نفسه بلا تغيير، والفواصل بين الجمل مسافات)،
       وتبقى «آمين» في سطر مستقل — فيتّسع المكان لتكبير الخطوط. */
    /* v2.84: «تعمّق» يبقى في الصورة، والخطوط تصغر لتتسع. */
    cardForShot.querySelectorAll('.prayer-text').forEach(pt => {
      const lines = pt.innerHTML.split(/\n/).map(x => x.trim()).filter(Boolean);
      if (lines.length < 2) return;
      const last = /^آمين/.test(lines[lines.length - 1]) ? lines.pop() : '';
      pt.innerHTML = lines.join(' ') + (last ? '<br>' + last : '');
    });
    const fitWrap = cardForShot.querySelector('.shot-fit-wrap');
    const fitOuter = cardForShot.querySelector('.shot-fit-outer');
    const scalable = fitWrap.querySelectorAll(
      '.verse-text, .verse-ref, .father-name, .father-ctx, .quote-text, .reflect-text, .prayer-text, .section-label, .extra-text, .extra-ref, .deep-text, .deep-label'
    );
    // Capture each element's own natural font-size once, before any
    // scaling, so later passes always multiply from the true original —
    // never compound on top of a previous scaling pass.
    const baseSizes = Array.from(scalable).map(el => parseFloat(getComputedStyle(el).fontSize) || 16);
    function applyTextScale(factor) {
      // Uses setProperty(...,'important') rather than a plain inline style,
      // so this dynamic fit-to-screen sizing always wins over the page's
      // own !important font-size rules (e.g. the settings-panel text-scale
      // rules), exactly like the un-themed v79 behaviour where no such
      // rules existed to compete with a plain inline style.
      scalable.forEach((el, i) => { el.style.setProperty('font-size', (baseSizes[i] * factor) + 'px', 'important'); });
    }

    applyTextScale(1);
    fitOuter.style.height = 'auto';
    const naturalH = fitWrap.scrollHeight;

    // Height of everything in the card OTHER than the scaled content
    // area (the fixed-size header: cross/date/topic block).
    const headerH = cardForShot.scrollHeight - naturalH;

    const availW = window.innerWidth;
    const availH = window.innerHeight - 10;
    // Work backwards from "the whole card must fill availW × availH"
    // to the content height (in the card's native 1080px-wide
    // coordinate system) that makes that true.
    const widthScale = availW / 1080;
    const desiredTotalNativeH = availH / widthScale;
    const targetContentH = Math.max(200, desiredTotalNativeH - headerH);

    // Grow the content up (short meditation) or shrink it down (long
    // one) toward that target by scaling each text element's actual
    // font-size — real CSS reflow, so lines always re-wrap to the
    // card's true width and can never spill past its edges, at any
    // scale. `.shot-fit-outer` stays height:auto, simply following
    // whatever height the resized text actually ends up needing, so a
    // rough estimate can under- or over-fill slightly but can never
    // clip content.
    let factor = Math.min(1.5, Math.max(0.4, targetContentH / naturalH));
    /* v75: لو أصغر خط في الصورة صار أقل من حدّ القراءة على هذه الشاشة، نُسقط مما هو للقراءة على الشاشة أولًا:
       «مقطع للتأمل» ثم «خلاصة التعليم» (الآية والتأمل والصلاة لا تُمَسّ أبدًا). */
    const MIN_PX = 11, refl = cardForShot.querySelector('.reflect-text');
    const reflBase = refl ? baseSizes[Array.from(scalable).indexOf(refl)] : 16;
    const tooSmall = () => { applyTextScale(factor); const sc = Math.min(widthScale, availH / cardForShot.scrollHeight); return reflBase * factor * sc < MIN_PX; };
    const refit = () => {
      applyTextScale(1); fitOuter.style.height = 'auto';
      const nH = fitWrap.scrollHeight, hH = cardForShot.scrollHeight - nH;
      factor = Math.min(1.5, Math.max(0.4, Math.max(200, desiredTotalNativeH - hH) / nH));
    };
    if (tooSmall()) { const eb = cardForShot.querySelector('.extra-box'); if (eb) { eb.remove(); refit(); } }
    if (tooSmall()) {
      const fm = cardForShot.querySelector('.merged-flow');
      const qt = fm && fm.querySelector('.quote-text');
      if (qt) { const lab = fm.querySelector('.section-label'), fn = fm.querySelector('.father-name'), fx = fm.querySelector('.father-ctx'), dv = fm.querySelector('.mini-divider');
        [lab, fn, fx, qt, dv].forEach(x => x && x.remove()); refit(); }
    }
    applyTextScale(factor);
    /* v2.84: العرض دائمًا بعرض الشاشة كاملًا؛ إن زاد الارتفاع نصغّر الخط (لا العرض). */
    for (let g = 0; g < 40 && factor > 0.4 && cardForShot.scrollHeight * widthScale > availH; g++) { factor *= 0.95; applyTextScale(factor); }

    const totalH = cardForShot.scrollHeight;
    const scale = Math.min(availW / 1080, availH / totalH);

    shotCardWidth = 1080;
    shotFitScale = scale;
    shotScale = scale;
    shotCard = cardForShot;
    applyShotScale();
  });
});

let shotScale = 1;
let shotFitScale = 1;
let shotCard = null;
let shotCardWidth = 1080;

function applyShotScale() {
  if (!shotCard) return;
  const stage = document.getElementById('shotStage');
  const cardW = shotCardWidth;
  const cardH = shotCard.scrollHeight;

  // The page is RTL, so an over-wide element overflows to the left;
  // anchoring the scale at the top-right keeps it inside the stage.
  shotCard.style.transformOrigin = 'top right';
  shotCard.style.transform = `scale(${shotScale})`;
  stage.style.width = (cardW * shotScale) + 'px';
  stage.style.height = (cardH * shotScale) + 'px';

}


document.getElementById('shotCloseBtn').addEventListener('click', () => {
  document.getElementById('shotOverlay').classList.remove('open');
});

/* ===================== الإعدادات (Settings) =====================
   تصميم 1 = شكل النسخة 79 الأصلي بالظبط (ثابت، بلا أي تخصيص).
   تصميم 2 = شكل النسخة 80 (كريمي/نبيتي)، وفيه 3 ألوان قابلة للتغيير:
   لون الخلفية، لون خلفية العرض (الكروت)، ولون خطوط العرض (نص الكروت).
   باقي الألوان (الحواشي، الدرجات الفاتحة/الغامقة) مشتقة منها تلقائيًا
   عبر color-mix() في الـCSS نفسه (شوف <style id="theme-v80">). */
const SETTINGS_KEY = 'khalwa_settings_v80';

const DEFAULT_COLORS = { bg:'#4A1420', surface:'#FFFBF2', ink:'#2E1D12' };
const DARK_PAGE_TEXT = { text:'#F6ECD6', soft:'#D9C6A3' };
const LIGHT_PAGE_TEXT = { text:'#2E1D12', soft:'#7A6248' };

const FONT_STEPS = [0.85, 1, 1.15, 1.3, 1.45];
const FONT_LABELS = ['85%', '100%', '115%', '130%', '145%'];

function loadSettings() {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      const isHex = v => typeof v === 'string' && /^#[0-9a-fA-F]{6}$/.test(v);
      // ترحيل المستخدمين القدامى: لو محفوظ عندهم تصميم 1 (داكن) أو 2 (فاتح) بدون
      // إعداد "مظهر" صريح، نستنتج مظهرهم الحالي من تصميمهم المحفوظ بدل ما نفاجئهم بتغيير.
      const validModes = ['auto', 'light', 'dark'];
      const inferredMode = parsed.design === '1' ? 'dark' : 'light';
      return {
        design: parsed.design === '1' ? '1' : '2',
        themeMode: validModes.includes(parsed.themeMode) ? parsed.themeMode : inferredMode,
        colors: { ...DEFAULT_COLORS }, /* v73: لا ألوان مخصّصة — الألوان تأتي من الثيمات (theme-core.js) */
        fontIndex: (typeof parsed.fontIndex === 'number' && parsed.fontIndex >= 0 && parsed.fontIndex < FONT_STEPS.length) ? parsed.fontIndex : 1,
        remindersEnabled: parsed.remindersEnabled === true
      };
    }
  } catch (e) {}
  return { design: '2', themeMode: 'light', colors: { ...DEFAULT_COLORS }, fontIndex: 1, remindersEnabled: false };
}

function saveSettings() {
  try {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(appSettings));
  } catch (e) {}
}

let appSettings = loadSettings();

// سطوع نسبي مبسّط لتحديد لون النص الواضح (فاتح أو غامق) فوق أي لون
// خلفية يختاره المستخدم بحرية — صيغة WCAG المختصرة.
function hexLuminance(hex) {
  const c = hex.replace('#', '');
  const r = parseInt(c.substring(0, 2), 16) / 255;
  const g = parseInt(c.substring(2, 4), 16) / 255;
  const b = parseInt(c.substring(4, 6), 16) / 255;
  const lin = v => (v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4));
  return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
}

function applyDesign(design) {
  document.documentElement.setAttribute('data-design', design);
  document.documentElement.setAttribute('data-theme', design === '1' ? 'dark' : 'light');
  const d1 = document.getElementById('design1Btn');
  const d2 = document.getElementById('design2Btn');
  if (d1 && d2) {
    d1.classList.toggle('active', design === '1');
    d2.classList.toggle('active', design === '2');
  }
  // قسم حجم الخط والألوان مخصوصين بتصميم 2 فقط (تصميم 1 يفضل ثابت زي v79 بالظبط)
  const fontSection = document.getElementById('fontSizeSection');
  if (fontSection) fontSection.style.display = '';
}

/* v73: منتقي الألوان الحر أُلغي. الألوان تُطبَّق من الثيم المختار في «الثيمات» (src/js/theme-core.js). */
function applyColors() { if (window.__rfTheme) window.__rfTheme.apply(); }

function applyFontScale(index) {
  const clamped = Math.max(0, Math.min(FONT_STEPS.length - 1, index));
  const ratio = FONT_STEPS[clamped];
  document.documentElement.style.fontSize = (ratio * 100) + '%';
  document.documentElement.style.setProperty('--txt-scale', ratio);
  const fval = document.getElementById('fontVal');
  if (fval) fval.textContent = FONT_LABELS[clamped];
}

/* ============ مظهر الخلفية: تلقائي / فاتح / داكن ============
   "فاتح" = تصميم 2 (كروت كريمي فاتحة)، "داكن" = تصميم 1 (كحلي/ذهبي غامق
   الأصلي)، و"تلقائي" يتتبّع تفضيل نظام تشغيل الجهاز (prefers-color-scheme)
   ويتغيّر لحظيًا لو المستخدم بدّل وضع جهازه وهو فاتح الصفحة، من غير ما
   يحتاج يرجع للإعدادات. */
const darkModeMql = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;

function resolveEffectiveDesign(mode) {
  if (mode === 'dark') return '1';
  if (mode === 'light') return '2';
  return (darkModeMql && darkModeMql.matches) ? '1' : '2';
}

function updateThemeModeButtons(mode) {
  const map = { auto: 'themeAutoBtn', light: 'themeLightBtn', dark: 'themeDarkBtn' };
  Object.entries(map).forEach(([m, id]) => {
    const btn = document.getElementById(id);
    if (btn) btn.classList.toggle('active', mode === m);
  });
}

function applyThemeMode(mode) {
  appSettings.themeMode = mode;
  updateThemeModeButtons(mode);
  const effective = resolveEffectiveDesign(mode);
  appSettings.design = effective;
  applyDesign(effective);
}

if (darkModeMql) {
  const onSchemeChange = () => {
    if (appSettings.themeMode === 'auto') {
      appSettings.design = resolveEffectiveDesign('auto');
      applyDesign(appSettings.design);
    }
  };
  if (darkModeMql.addEventListener) darkModeMql.addEventListener('change', onSchemeChange);
  else if (darkModeMql.addListener) darkModeMql.addListener(onSchemeChange); // متصفحات قديمة
}

function applyAllSettings() {
  applyThemeMode(appSettings.themeMode);
  applyColors(appSettings.colors);
  applyFontScale(appSettings.fontIndex);
}

function openSettingsPanel() {
  document.getElementById('settingsPanel').classList.add('open');
  document.getElementById('settingsBackdrop').classList.add('open');
}

function closeSettingsPanel() {
  document.getElementById('settingsPanel').classList.remove('open');
  document.getElementById('settingsBackdrop').classList.remove('open');
}

