/* ============ تذكير مواعيد الصلاة (Notification API محلي) ============
   يعمل فقط أثناء فتح الصفحة (أو بعد تثبيتها كتطبيق وهي تعمل في الخلفية على
   الأجهزة التي تسمح بذلك) — لا يوجد سيرفر يرسل تنبيهات لصفحة مغلقة تمامًا. */
let reminderTimer = null;

function msUntilNextReminder() {
  const now = new Date();
  const nowDec = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
  let best = null;
  Object.entries(HOUR_REMINDER_TIMES).forEach(([key, t]) => {
    let diff = t - nowDec;
    if (diff <= 0) diff += 24;
    if (best === null || diff < best.diff) best = { key, diff };
  });
  return { key: best.key, ms: Math.max(1000, best.diff * 3600 * 1000) };
}

function scheduleNextReminder() {
  if (reminderTimer) { clearTimeout(reminderTimer); reminderTimer = null; }
  if (!appSettings.remindersEnabled) return;
  if (!('Notification' in window) || Notification.permission !== 'granted') return;
  const { key, ms } = msUntilNextReminder();
  reminderTimer = setTimeout(() => {
    const h = HOURS[key];
    try {
      (window.__rfNotify || function (t, o) { new Notification(t, o); })('حان وقت صلاة ' + (h ? h.label : 'الأجبية'), {
        body: h ? (h.label + ' — ' + h.sub) : 'حان وقت إحدى ساعات الأجبية.',
        tag: 'khalwa-hour-' + key,
        lang: 'ar'
      });
    } catch (e) {}
    scheduleNextReminder();
  }, ms);
}

function setRemindersEnabled(on) {
  appSettings.remindersEnabled = on;
  saveSettings();
  const toggle = document.getElementById('remindersToggle');
  if (toggle) toggle.setAttribute('aria-checked', on ? 'true' : 'false');
  if (on) scheduleNextReminder();
  else if (reminderTimer) { clearTimeout(reminderTimer); reminderTimer = null; }
}

const remindersToggleEl = document.getElementById('remindersToggle');
if (remindersToggleEl) {
  remindersToggleEl.setAttribute('aria-checked', appSettings.remindersEnabled ? 'true' : 'false');
  remindersToggleEl.addEventListener('click', () => {
    if (!appSettings.remindersEnabled) {
      if (!('Notification' in window)) {
        window.__say('متصفحك الحالي لا يدعم التنبيهات المحلية.');
        return;
      }
      if (Notification.permission === 'granted') {
        setRemindersEnabled(true);
      } else if (Notification.permission !== 'denied') {
        Notification.requestPermission().then(perm => {
          if (perm === 'granted') setRemindersEnabled(true);
        });
      } else {
        window.__say('الإشعارات ممنوعة حاليًا من إعدادات المتصفح لهذا الموقع. فعّلها من هناك أولًا ثم أعد المحاولة.');
      }
    } else {
      setRemindersEnabled(false);
    }
  });
}
if (appSettings.remindersEnabled && 'Notification' in window && Notification.permission === 'granted') {
  scheduleNextReminder();
}

/* ============ تسجيل Service Worker للعمل بدون إنترنت ============
   يتجاهل نفسه تلقائيًا لو الملف مفتوح مباشرة (file://) أو sw.js غير
   موجود بجانب الملف — بدون أي رسالة خطأ تظهر للمستخدم. */
if ('serviceWorker' in navigator && (location.protocol === 'https:' || location.hostname === 'localhost')) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js').catch(() => {});
  });
}


